#include <bits/stdc++.h>
using namespace std;
#define ll long long
ll lsc[62], rsc[62], rsc2[62];
char s[62];
map<pair<ll,int>,ll> nm, mm;

ll comb(int n, int k) {
    if (n < k || k < 0) return 0;
    ll res = 1;
    for (int i = 0; i < k; i++) {
        res = res * (n - i) / (i + 1);
    }
    return res;
}

int main() {
    int R, C, total, idx, aCount=0, bCount=0, cond, aIdx, bIdx;
    ll totalSum=0, halfSum=0, bSum, answer=0;
    scanf("%d%d\n", &R, &C);
    total = 2 * (R + C);
    scanf("%s", s);
    lsc[2*R - 1] = 1;
    for (idx = 2*R; idx < total; idx++)
        lsc[idx] = lsc[idx-1] * idx / (idx - 2*R + 1);
    for (idx = 0; idx <= total; idx++) {
        rsc[idx] = comb(idx, R);
        rsc2[idx] = comb(idx, R - 1);
    }
    halfSum = rsc[total/2] * rsc[total/2];
    for (idx = total - 1; idx >= 0; idx--) {
        if (totalSum > 0) cond = 1; else cond = 0;
        if (bCount == total/2) cond = 1;
        if (aCount == total/2) cond = 0;
        if (cond) {
            aCount++;
            totalSum -= rsc2[total/2 - aCount] * rsc[total/2 - bCount];
        } else {
            bCount++;
            totalSum += rsc2[total/2 - bCount] * rsc[total/2 - aCount];
        }
    }
    totalSum = max(totalSum, -totalSum);
    mm[{0,0}] = 1;
    for (idx = total - 1; idx >= 2*R - 1; idx--) {
        nm.clear();
        for (auto &pair : mm) {
            ll sumVal = pair.first.first;
            ll countVal = pair.second;
            int cnt = pair.first.second;
            aIdx = total/2 - cnt;
            bIdx = idx + 1 - aIdx;
            ll aSumVal = sumVal + rsc2[aIdx - 1] * rsc[bIdx];
            ll bSumVal = sumVal - rsc2[bIdx - 1] * rsc[aIdx];
            if (s[idx] == 'A') {
                nm[{aSumVal, cnt + 1}] += countVal;
                nm[{bSumVal, cnt}] += 0;
            } else if (s[idx] == 'B') {
                nm[{aSumVal, cnt + 1}] += 0;
                nm[{bSumVal, cnt}] += countVal;
            } else {
                nm[{aSumVal, cnt + 1}] += countVal;
                nm[{bSumVal, cnt}] += countVal;
            }
        }
        totalSum -= lsc[idx];
        mm.clear();
        for (auto &it : nm) {
            ll sumVal = it.first.first;
            ll ncnt = it.second;
            int cnt = it.first.second;
            aIdx = total/2 - cnt;
            bIdx = idx - aIdx;
            if (cnt > total/2 || total - idx - cnt > total/2) continue;
            if (sumVal < -halfSum - rsc[aIdx] * rsc[bIdx] || sumVal > halfSum + rsc[aIdx] * rsc[bIdx]) continue;
            mm[{sumVal, cnt}] += ncnt;
        }
    }
    bSum = 1e18;
    for (auto &it : mm) {
        bSum = min(bSum, max(it.first.first, -it.first.first));
    }
    for (auto &it : mm) {
        ll sumVal = it.first.first;
        ll ncnt = it.second;
        int cnt = it.first.second;
        if (sumVal == bSum || sumVal == -bSum) {
            int sem = 0;
            for (idx = 0; idx < 2*R - 1; idx++)
                if (s[idx] == '?') sem++;
                else if (s[idx] == 'A') cnt++;
            ncnt *= comb(sem, total/2 - cnt);
            answer += ncnt;
        }
    }
    printf("%lld\n", answer);
    return 0;
}
